using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Diagnostics;
using System.ServiceProcess;
namespace ZapretManager {
public static class SaveExclusionTests {
 public static async Task<int> Run(string report){var lines=new List<string>();int failures=0;Action<bool,string> check=(ok,name)=>{lines.Add((ok?"PASS: ":"FAIL: ")+name);if(!ok)failures++;File.WriteAllLines(report,lines);};string originalService=Core.Service,originalHelper=Exclusions.ServiceName;string[] files={"manager-base.txt","config.txt","manager-settings.json","app-exclusions.json"};byte[][] old=files.Select(f=>File.Exists(Core.PathOf(f))?File.ReadAllBytes(Core.PathOf(f)):null).ToArray();string a=Core.PathOf("app\\save-probe-a.exe"),b=Core.PathOf("app\\save-probe-b.exe");IntPtr observer=IntPtr.Zero;Task receiving=null;int seen=0;try{
  Core.Service="zapret2-save-engine-test";Exclusions.ServiceName="zapret2-save-helper-test";Exclusions.Testing=true;
  if(Core.State()!="NotInstalled"||Exclusions.State()!="NotInstalled")throw new Exception("Save test services already exist");
  string exe=System.Reflection.Assembly.GetExecutingAssembly().Location;File.Copy(exe,a,true);File.Copy(exe,b,true);
  File.WriteAllText(Core.PathOf("manager-base.txt"),"--wf-tcp-out=1\r\n--filter-tcp=1\r\n",System.Text.Encoding.ASCII);Core.Write(Core.PathOf("manager-settings.json"),new Settings {Game="off",IPSet="none",AutoStart=false});Core.Write(Core.PathOf("app-exclusions.json"),new ExclusionConfig {Enabled=false});await Core.Install(CancellationToken.None);
  ExclusionWorker.Initialize();observer=ExclusionWorker.WinDivertOpen("outbound and udp and ip.DstAddr == 192.0.2.123 and udp.DstPort == 43999",0,0,5);if(observer==new IntPtr(-1))throw new System.ComponentModel.Win32Exception(System.Runtime.InteropServices.Marshal.GetLastWin32Error());IntPtr handle=observer;receiving=Task.Run(()=>{var packet=new byte[65575];var address=new byte[80];uint size;while(ExclusionWorker.WinDivertRecv(handle,packet,(uint)packet.Length,out size,address))Interlocked.Increment(ref seen);});
  var config=new ExclusionConfig {Applications=new[]{a}};await Exclusions.Save(config);var status=Core.Read<ExclusionHealth>(Core.PathOf("app-exclusions-status.json"));check(status.Ready&&status.RequestId==config.RequestId&&status.PID==Core.GetServicePID(Exclusions.ServiceName),"real Save acknowledges exact request and running helper PID");
  int before=seen;await Core.Run(a,"--exclusion-probe",CancellationToken.None);await Task.Delay(200);check(seen==before,"Save of arbitrary EXE actually bypasses its UDP traffic");await Core.Run(b,"--exclusion-probe",CancellationToken.None);await Task.Delay(200);check(seen-before>=8,"other EXE remains on normal path after Save");
  string statusFile=Core.PathOf("app-exclusions-status.json");Task saving;using(var locked=new FileStream(statusFile,FileMode.Open,FileAccess.Read,FileShare.Read)){var next=new ExclusionConfig {Applications=new[]{b}};saving=Task.Run(()=>Exclusions.Save(next));await Task.Delay(700);check(!saving.IsCompleted,"stale acknowledgement cannot confirm a different Save while status is locked");await Task.Delay(1300);check(Exclusions.State()=="Running","temporary status file lock does not kill helper worker/service");}await saving;check(Core.Read<ExclusionHealth>(statusFile).RequestId==Exclusions.Load().RequestId,"Save succeeds after status-file lock is released");
  before=seen;await Core.Run(b,"--exclusion-probe",CancellationToken.None);await Task.Delay(200);check(seen==before,"new EXE exclusion remains functional after status-file lock");
  DateTime stamp=File.GetLastWriteTimeUtc(Core.PathOf("app-exclusions.json"));config=new ExclusionConfig {RequestId=Guid.NewGuid().ToString("N"),Applications=new[]{a}};Core.Write(Core.PathOf("app-exclusions.json"),config);File.SetLastWriteTimeUtc(Core.PathOf("app-exclusions.json"),stamp);bool applied=false;for(int n=0;n<50;n++){await Task.Delay(100);status=Core.Read<ExclusionHealth>(statusFile);if(status.RequestId==config.RequestId&&status.Ready){applied=true;break;}}check(applied,"changed request reloads even when filesystem timestamp is identical");
  for(int n=0;n<5;n++){config=new ExclusionConfig {Applications=new[]{n%2==0?a:b}};await Exclusions.Save(config);}check(Core.Read<ExclusionHealth>(statusFile).RequestId==config.RequestId,"five consecutive edits acknowledge the latest list");
  await Exclusions.Save(new ExclusionConfig {Enabled=false,Applications=new[]{a,b}});before=seen;await Core.Run(a,"--exclusion-probe",CancellationToken.None);await Task.Delay(200);check(seen-before>=8,"Save disabling exclusions returns packets to normal path");
  await Exclusions.Save(new ExclusionConfig {Applications=new string[0]});check(Core.Read<ExclusionHealth>(statusFile).Ready,"empty list acknowledges without incoming traffic");
  await Exclusions.Save(new ExclusionConfig {Applications=new[]{a,b}});before=seen;await Core.Run(a,"--exclusion-probe",CancellationToken.None);await Core.Run(b,"--exclusion-probe",CancellationToken.None);await Task.Delay(200);check(seen==before,"two arbitrary applications can both be excluded");
  File.WriteAllText(Core.PathOf("exclusion-worker-fault.test"),"inject");bool failed=false,recovered=false;for(int n=0;n<100;n++){await Task.Delay(100);status=Core.Read<ExclusionHealth>(statusFile);if(!status.Ready&&status.Error.Contains("test injected"))failed=true;if(failed&&status.Ready&&status.Error==""){recovered=true;break;}}check(failed&&recovered&&Exclusions.State()=="Running","helper recovers from an injected worker failure without restarting engine/service");await Exclusions.Save(new ExclusionConfig {Applications=new[]{b}});check(Core.Read<ExclusionHealth>(statusFile).RequestId==Exclusions.Load().RequestId,"Save works after automatic worker recovery");
  Core.Control("Off");config=new ExclusionConfig {Applications=new[]{b}};await Exclusions.Save(config);check(Exclusions.Load().RequestId==config.RequestId,"Save while zapret is stopped persists without waiting for inactive service");Core.Control("On");before=seen;await Core.Run(b,"--exclusion-probe",CancellationToken.None);await Task.Delay(200);check(seen==before,"saved list is applied on next engine start");
 }catch(Exception e){check(false,e.ToString());}finally{if(observer!=IntPtr.Zero&&observer!=new IntPtr(-1)){ExclusionWorker.WinDivertShutdown(observer,1);if(receiving!=null)receiving.GetAwaiter().GetResult();ExclusionWorker.WinDivertClose(observer);}try{if(Core.Service=="zapret2-save-engine-test"&&Core.State()!="NotInstalled")Core.Remove(CancellationToken.None).GetAwaiter().GetResult();if(Exclusions.ServiceName=="zapret2-save-helper-test")Exclusions.Remove().GetAwaiter().GetResult();}catch(Exception e){check(false,"cleanup: "+e.Message);}Core.Service=originalService;Exclusions.ServiceName=originalHelper;Exclusions.Testing=false;for(int n=0;n<files.Length;n++){if(old[n]==null){if(File.Exists(Core.PathOf(files[n])))File.Delete(Core.PathOf(files[n]));}else File.WriteAllBytes(Core.PathOf(files[n]),old[n]);}foreach(string path in new[]{a,b})if(File.Exists(path))File.Delete(path);}lines.Add("Failures: "+failures);File.WriteAllLines(report,lines);return failures==0?0:1;
 }
}
}
